/**
 * Native-app Phase 2: emit `rust/ai-fighters/src/presets_data.rs` from the TS
 * weight presets.
 *
 *   bun tools/native-app/dump-rust-presets.ts
 *
 * The generated file is pure data (`HoikoWeights` literals): the VS weight list
 * `we`/`wo`/`wd`/`wr` (in `TransitionWeight` index order) plus the solo preset
 * tables `ultra2`/`sprint`. The fighters crate's preset test separately asserts
 * this data against `evidence/native-app/hoiko-weights.json`, so regeneration
 * drift is caught.
 */

import { writeFileSync } from "node:fs";
import { hoikoPresetWeights, hoikoWeightList } from "../../src/ai/hoiko-weights.js";

const list = hoikoWeightList("we");
const ultra2 = hoikoPresetWeights("ultra2");
const sprint = hoikoPresetWeights("sprint");

const array = (values: readonly number[]): string => `[${values.join(", ")}]`;

const entry = (value: (typeof list)[number], indent: string): string =>
  `${indent}HoikoWeights {
${indent}    weight: ${array(value.weight)},
${indent}    column: ${array(value.column)},
${indent}    combo_table: ${array(value.comboTable)},
${indent}    nexus: ${value.nexus},
${indent}},`;

const vs = list.map((value) => entry(value, "    ")).join("\n");
const solo = (value: (typeof list)[number]): string => entry(value, "    ").replace(/,$/, "");

const text = `//! Generated by \`bun tools/native-app/dump-rust-presets.ts\` — do not edit by hand.
//!
//! The faithful weight tables: \`hoikoWeightList("we")\` (the four shipping VS
//! weight files \`we\`/\`wo\`/\`wd\`/\`wr\` in \`TransitionWeight\` index order) and
//! the solo preset files \`ultra2\`/\`sprint\` (\`hoikoWeightList\` duplicates the
//! solo table to a two-entry list).

use hoiko_core::HoikoWeights;

/// \`src/ai/hoiko-weights.ts\` \`hoikoWeightList("we")\`.
pub const VS_WEIGHT_LIST: [HoikoWeights; ${list.length}] = [
${vs}
];

/// \`src/ai/hoiko-weights.ts\` \`hoikoPresetWeights("ultra2")\`.
pub const ULTRA2_WEIGHTS: HoikoWeights =
${solo(ultra2)};

/// \`src/ai/hoiko-weights.ts\` \`hoikoPresetWeights("sprint")\`.
pub const SPRINT_WEIGHTS: HoikoWeights =
${solo(sprint)};
`;

const out = new URL("../../rust/ai-fighters/src/presets/presets_data.rs", import.meta.url);
writeFileSync(out, text);
console.log(
  `wrote rust/ai-fighters/src/presets/presets_data.rs (${list.length} VS entries + 2 solo)`,
);
